return [
  {
    json: {
      workflow: {
        id: "WF-0010",
        name: "Object Auditor",
        version: "0.1.0",
        status: "draft"
      },

      audit: {
        enabledRules: [
          "duplicate_object_id",
          "invalid_object_id",
          "missing_status",
          "invalid_status",
          "object_missing_in_registry",
          "registry_entry_without_object",
          "missing_relation_target"
        ]
      },

      severity: {
        info: "info",
        warning: "warning",
        error: "error"
      },

      output: {
        includeSummary: true,
        includeFindings: true,
        includeTechnicalErrors: true
      },

      safety: {
        readOnly: true,
        allowRepositoryChanges: false,
        allowCommits: false,
        allowAutomaticRepair: false
      }
    }
  }
];

const config = $input.first().json;

const objects = [
  {
    objectId: "COMP-0001",
    objectType: "company",
    title: "JaMoKo",
    status: "active",
    path: "01_Objects/Company/COMP-0001/object.md",
    relationships: []
  },
  {
    objectId: "CUST-0001",
    objectType: "customer",
    title: "SL-Bautec",
    status: "active",
    path: "01_Objects/Customers/CUST-0001/object.md",
    relationships: []
  },
  {
    objectId: "CUST-0002",
    objectType: "customer",
    title: "Uli Glaser",
    status: null,
    path: "01_Objects/Customers/CUST-0002/object.md",
    relationships: []
  },
  {
    objectId: "PROJ-0001",
    objectType: "project",
    title: "JaMoKo Website",
    status: "active",
    path: "01_Objects/Projects/PROJ-0001/object.md",
    relationships: [
      {
        type: "belongs_to",
        targetId: "COMP-0001"
      }
    ]
  }
];

return [
  {
    json: {
      ...config,

      objects,

      objectCount: objects.length,

      source: {
        workflowId: "WF-0008",
        workflowName: "Object Loader",
        mode: "controlled_test_data"
      }
    }
  }
];

const input = $input.first().json;

const registryEntries = [
  {
    objectId: "COMP-0001",
    objectType: "company",
    title: "JaMoKo",
    status: "active",
    path: "01_Objects/Company/COMP-0001/object.md"
  },
  {
    objectId: "CUST-0001",
    objectType: "customer",
    title: "SL-Bautec",
    status: "active",
    path: "01_Objects/Customers/CUST-0001/object.md"
  },
  {
    objectId: "PROJ-0001",
    objectType: "project",
    title: "JaMoKo Website",
    status: "active",
    path: "01_Objects/Projects/PROJ-0001/object.md"
  },
  {
    objectId: "WEB-0001",
    objectType: "website",
    title: "JaMoKo Website",
    status: "active",
    path: "01_Objects/Websites/WEB-0001/object.md"
  }
];

const allowedStatusValues = [
  "draft",
  "planned",
  "development",
  "testing",
  "active",
  "waiting",
  "review",
  "released",
  "completed",
  "deprecated",
  "archived"
];

const allowedRelationTypes = [
  "belongs_to",
  "contains",
  "depends_on",
  "related_to",
  "uses",
  "maintained_by"
];

return [
  {
    json: {
      ...input,

      registry: {
        entries: registryEntries,
        entryCount: registryEntries.length,
        source: "controlled_test_data"
      },

      statusRegistry: {
        values: allowedStatusValues,
        valueCount: allowedStatusValues.length
      },

      relationRegistry: {
        values: allowedRelationTypes,
        valueCount: allowedRelationTypes.length
      }
    }
  }
];

const input = $input.first().json;

const objects = input.objects ?? [];
const registryEntries = input.registry?.entries ?? [];
const statusValues = input.statusRegistry?.values ?? [];
const relationTypes = input.relationRegistry?.values ?? [];

const objectIndex = {};
const registryIndex = {};

for (const object of objects) {
  objectIndex[object.objectId] = object;
}

for (const entry of registryEntries) {
  registryIndex[entry.objectId] = entry;
}

return [
  {
    json: {
      ...input,

      auditContext: {
        objects,
        registryEntries,
        statusValues,
        relationTypes,

        objectIndex,
        registryIndex,

        statistics: {
          objectCount: objects.length,
          registryCount: registryEntries.length,
          statusCount: statusValues.length,
          relationCount: relationTypes.length
        }
      }
    }
  }
];

const input = $input.first().json;
const context = input.auditContext ?? {};
const objects = Array.isArray(context.objects)
  ? context.objects
  : [];

const findings = [];
const technicalErrors = [];

const objectIdPattern =
  /^(COMP|CUST|PROJ|WEB|DEV|REPO|WF|INV|INC|FIN|STD|HYP|DEC)-\d{4}$/;

const occurrences = {};

// IDs sammeln
for (const object of objects) {
  const objectId =
    typeof object.objectId === "string"
      ? object.objectId.trim().toUpperCase()
      : null;

  if (!objectId) {
    findings.push({
      objectId: null,
      path: object.path ?? null,
      category: "identity",
      severity: "error",
      rule: "missing_object_id",
      message: "Die Objektakte besitzt keine objectId."
    });

    continue;
  }

  if (!occurrences[objectId]) {
    occurrences[objectId] = [];
  }

  occurrences[objectId].push(object);

  // Format prüfen
  if (!objectIdPattern.test(objectId)) {
    findings.push({
      objectId,
      path: object.path ?? null,
      category: "identity",
      severity: "error",
      rule: "invalid_object_id",
      message: `Die Objekt-ID ${objectId} entspricht nicht dem erwarteten Format PREFIX-0000.`
    });
  }

  // ID gegen Dateipfad prüfen
  const pathObjectId =
    String(object.path ?? "")
      .match(/[A-Z]+-\d{4}/i)?.[0]
      ?.toUpperCase() ?? null;

  if (pathObjectId && pathObjectId !== objectId) {
    findings.push({
      objectId,
      path: object.path ?? null,
      category: "identity",
      severity: "error",
      rule: "object_id_path_mismatch",
      message:
        `Die objectId ${objectId} stimmt nicht mit der ID ${pathObjectId} im Dateipfad überein.`
    });
  }
}

// Doppelte IDs prüfen
for (const [objectId, matchingObjects] of Object.entries(occurrences)) {
  if (matchingObjects.length > 1) {
    findings.push({
      objectId,
      path: null,
      category: "identity",
      severity: "error",
      rule: "duplicate_object_id",
      message:
        `Die Objekt-ID ${objectId} wurde ${matchingObjects.length}-mal gefunden.`,
      details: matchingObjects.map(object => ({
        path: object.path ?? null,
        title: object.title ?? null,
        objectType: object.objectType ?? null
      }))
    });
  }
}

return [
  {
    json: {
      ...input,

      identityAudit: {
        checkedObjects: objects.length,
        findings,
        technicalErrors,
        counts: {
          findings: findings.length,
          errors: findings.filter(
            finding => finding.severity === "error"
          ).length,
          warnings: findings.filter(
            finding => finding.severity === "warning"
          ).length,
          technicalErrors: technicalErrors.length
        }
      }
    }
  }
];

const input = $input.first().json;

const context = input.auditContext ?? {};

const objects = Array.isArray(context.objects)
  ? context.objects
  : [];

const allowedStatusValues = Array.isArray(context.statusValues)
  ? context.statusValues.map(value =>
      String(value).trim().toLowerCase()
    )
  : [];

const findings = [];
const technicalErrors = [];

for (const object of objects) {
  const objectId = object.objectId ?? null;
  const path = object.path ?? null;

  const rawStatus = object.status;

  const status =
    typeof rawStatus === "string"
      ? rawStatus.trim().toLowerCase()
      : null;

  if (!status) {
    findings.push({
      objectId,
      path,
      category: "status",
      severity: "error",
      rule: "missing_status",
      message: "Das Pflichtfeld 'status' fehlt oder ist leer."
    });

    continue;
  }

  if (!allowedStatusValues.includes(status)) {
    findings.push({
      objectId,
      path,
      category: "status",
      severity: "error",
      rule: "invalid_status",
      message:
        `Der Status '${status}' ist nicht im Statusregister enthalten.`,
      details: {
        currentStatus: status,
        allowedStatusValues
      }
    });
  }
}

if (allowedStatusValues.length === 0) {
  technicalErrors.push({
    category: "technical",
    severity: "error",
    rule: "status_registry_empty",
    message:
      "Das Statusregister enthält keine zulässigen Statuswerte."
  });
}

return [
  {
    json: {
      ...input,

      statusAudit: {
        checkedObjects: objects.length,
        allowedStatusValues,
        findings,
        technicalErrors,

        counts: {
          findings: findings.length,

          errors: findings.filter(
            finding => finding.severity === "error"
          ).length,

          warnings: findings.filter(
            finding => finding.severity === "warning"
          ).length,

          technicalErrors: technicalErrors.length
        }
      }
    }
  }
];

const input = $input.first().json;

const context = input.auditContext ?? {};

const objects = Array.isArray(context.objects)
  ? context.objects
  : [];

const registryEntries = Array.isArray(context.registryEntries)
  ? context.registryEntries
  : [];

const findings = [];
const technicalErrors = [];

const objectIndex = {};
const registryIndex = {};

// Objektindex aufbauen
for (const object of objects) {
  const objectId =
    typeof object.objectId === "string"
      ? object.objectId.trim().toUpperCase()
      : null;

  if (!objectId) {
    continue;
  }

  if (!objectIndex[objectId]) {
    objectIndex[objectId] = [];
  }

  objectIndex[objectId].push(object);
}

// Registerindex aufbauen
for (const entry of registryEntries) {
  const objectId =
    typeof entry.objectId === "string"
      ? entry.objectId.trim().toUpperCase()
      : null;

  if (!objectId) {
    technicalErrors.push({
      category: "technical",
      severity: "error",
      rule: "registry_entry_missing_object_id",
      message: "Ein Registereintrag besitzt keine objectId.",
      details: {
        entry
      }
    });

    continue;
  }

  if (!registryIndex[objectId]) {
    registryIndex[objectId] = [];
  }

  registryIndex[objectId].push(entry);
}

// Objektakte ohne Registereintrag
for (const [objectId, matchingObjects] of Object.entries(objectIndex)) {
  if (!registryIndex[objectId]) {
    for (const object of matchingObjects) {
      findings.push({
        objectId,
        path: object.path ?? null,
        category: "registry",
        severity: "warning",
        rule: "object_missing_in_registry",
        message:
          `Die Objektakte ${objectId} besitzt keinen Eintrag im Hauptregister.`
      });
    }
  }
}

// Registereintrag ohne Objektakte
for (const [objectId, matchingEntries] of Object.entries(registryIndex)) {
  if (!objectIndex[objectId]) {
    for (const entry of matchingEntries) {
      findings.push({
        objectId,
        path: entry.path ?? null,
        category: "registry",
        severity: "error",
        rule: "registry_entry_without_object",
        message:
          `Der Registereintrag ${objectId} besitzt keine vorhandene Objektakte.`
      });
    }
  }
}

// Doppelte Registereinträge
for (const [objectId, matchingEntries] of Object.entries(registryIndex)) {
  if (matchingEntries.length > 1) {
    findings.push({
      objectId,
      path: null,
      category: "registry",
      severity: "error",
      rule: "duplicate_registry_entry",
      message:
        `Die Objekt-ID ${objectId} wurde ${matchingEntries.length}-mal im Hauptregister gefunden.`,
      details: matchingEntries.map(entry => ({
        path: entry.path ?? null,
        title: entry.title ?? null,
        objectType: entry.objectType ?? null
      }))
    });
  }
}

// Pfadabweichungen prüfen
for (const objectId of Object.keys(objectIndex)) {
  const matchingObjects = objectIndex[objectId];
  const matchingEntries = registryIndex[objectId];

  if (!matchingEntries) {
    continue;
  }

  for (const object of matchingObjects) {
    for (const entry of matchingEntries) {
      const objectPath = String(object.path ?? "").trim();
      const registryPath = String(entry.path ?? "").trim();

      if (
        objectPath &&
        registryPath &&
        objectPath !== registryPath
      ) {
        findings.push({
          objectId,
          path: objectPath,
          category: "registry",
          severity: "warning",
          rule: "registry_path_mismatch",
          message:
            `Der Objektpfad '${objectPath}' stimmt nicht mit dem Registerpfad '${registryPath}' überein.`,
          details: {
            objectPath,
            registryPath
          }
        });
      }
    }
  }
}

return [
  {
    json: {
      ...input,

      registryAudit: {
        checkedObjects: objects.length,
        checkedRegistryEntries: registryEntries.length,

        findings,
        technicalErrors,

        counts: {
          findings: findings.length,

          errors: findings.filter(
            finding => finding.severity === "error"
          ).length,

          warnings: findings.filter(
            finding => finding.severity === "warning"
          ).length,

          technicalErrors: technicalErrors.length
        }
      }
    }
  }
];

const input = $input.first().json;

const context = input.auditContext ?? {};

const objects = Array.isArray(context.objects)
  ? context.objects
  : [];

const relationTypes = Array.isArray(context.relationTypes)
  ? context.relationTypes.map(value =>
      String(value).trim().toLowerCase()
    )
  : [];

const objectIndex = context.objectIndex ?? {};

const findings = [];
const technicalErrors = [];

for (const object of objects) {
  const relationships = Array.isArray(object.relationships)
    ? object.relationships
    : [];

  for (const relationship of relationships) {
    const relationType =
      typeof relationship.type === "string"
        ? relationship.type.trim().toLowerCase()
        : null;

    const targetId =
      typeof relationship.targetId === "string"
        ? relationship.targetId.trim().toUpperCase()
        : null;

    if (!targetId) {
      findings.push({
        objectId: object.objectId ?? null,
        path: object.path ?? null,
        category: "relationship",
        severity: "error",
        rule: "missing_relation_target_id",
        message:
          "Eine Beziehung besitzt keine Ziel-ID.",
        details: {
          relationship
        }
      });

      continue;
    }

    if (!objectIndex[targetId]) {
      findings.push({
        objectId: object.objectId ?? null,
        path: object.path ?? null,
        category: "relationship",
        severity: "error",
        rule: "missing_relation_target",
        message:
          `Das referenzierte Zielobjekt ${targetId} wurde nicht gefunden.`,
        details: {
          relationType,
          targetId
        }
      });
    }

    if (!relationType) {
      findings.push({
        objectId: object.objectId ?? null,
        path: object.path ?? null,
        category: "relationship",
        severity: "warning",
        rule: "missing_relation_type",
        message:
          `Die Beziehung zum Zielobjekt ${targetId} besitzt keinen Beziehungstyp.`,
        details: {
          targetId
        }
      });

      continue;
    }

    if (
      relationTypes.length > 0 &&
      !relationTypes.includes(relationType)
    ) {
      findings.push({
        objectId: object.objectId ?? null,
        path: object.path ?? null,
        category: "relationship",
        severity: "warning",
        rule: "invalid_relation_type",
        message:
          `Der Beziehungstyp '${relationType}' ist nicht im Beziehungsregister enthalten.`,
        details: {
          relationType,
          targetId,
          allowedRelationTypes: relationTypes
        }
      });
    }
  }
}

if (relationTypes.length === 0) {
  technicalErrors.push({
    category: "technical",
    severity: "warning",
    rule: "relation_registry_empty",
    message:
      "Das Beziehungsregister enthält keine zulässigen Beziehungstypen."
  });
}

return [
  {
    json: {
      ...input,

      relationshipAudit: {
        checkedObjects: objects.length,
        checkedRelationships: objects.reduce(
          (sum, object) =>
            sum +
            (
              Array.isArray(object.relationships)
                ? object.relationships.length
                : 0
            ),
          0
        ),

        findings,
        technicalErrors,

        counts: {
          findings: findings.length,

          errors: findings.filter(
            finding => finding.severity === "error"
          ).length,

          warnings: findings.filter(
            finding => finding.severity === "warning"
          ).length,

          technicalErrors: technicalErrors.length
        }
      }
    }
  }
];

const input = $input.first().json;

const identityAudit = input.identityAudit ?? {};
const statusAudit = input.statusAudit ?? {};
const registryAudit = input.registryAudit ?? {};
const relationshipAudit = input.relationshipAudit ?? {};

const findings = [
  ...(Array.isArray(identityAudit.findings)
    ? identityAudit.findings
    : []),

  ...(Array.isArray(statusAudit.findings)
    ? statusAudit.findings
    : []),

  ...(Array.isArray(registryAudit.findings)
    ? registryAudit.findings
    : []),

  ...(Array.isArray(relationshipAudit.findings)
    ? relationshipAudit.findings
    : [])
];

const technicalErrors = [
  ...(Array.isArray(identityAudit.technicalErrors)
    ? identityAudit.technicalErrors
    : []),

  ...(Array.isArray(statusAudit.technicalErrors)
    ? statusAudit.technicalErrors
    : []),

  ...(Array.isArray(registryAudit.technicalErrors)
    ? registryAudit.technicalErrors
    : []),

  ...(Array.isArray(relationshipAudit.technicalErrors)
    ? relationshipAudit.technicalErrors
    : [])
];

const groupedFindings = {
  info: findings.filter(
    finding => finding.severity === "info"
  ),

  warnings: findings.filter(
    finding => finding.severity === "warning"
  ),

  errors: findings.filter(
    finding => finding.severity === "error"
  )
};

const affectedObjectIds = [
  ...new Set(
    findings
      .map(finding => finding.objectId)
      .filter(Boolean)
  )
];

return [
  {
    json: {
      ...input,

      auditFindings: {
        all: findings,

        grouped: groupedFindings,

        technicalErrors,

        affectedObjectIds,

        counts: {
          total: findings.length,
          info: groupedFindings.info.length,
          warnings: groupedFindings.warnings.length,
          errors: groupedFindings.errors.length,
          technicalErrors: technicalErrors.length,
          affectedObjects: affectedObjectIds.length
        }
      }
    }
  }
];

const input = $input.first().json;

const findings = input.auditFindings ?? {};
const counts = findings.counts ?? {
  total: 0,
  info: 0,
  warnings: 0,
  errors: 0,
  technicalErrors: 0,
  affectedObjects: 0
};

let auditStatus = "passed";

if (counts.errors > 0 || counts.technicalErrors > 0) {
  auditStatus = "failed";
} else if (counts.warnings > 0) {
  auditStatus = "warning";
}

const healthScoreBase = 100;

const errorPenalty = counts.errors * 15;
const warningPenalty = counts.warnings * 5;
const technicalPenalty = counts.technicalErrors * 20;

const healthScore = Math.max(
  0,
  healthScoreBase -
    errorPenalty -
    warningPenalty -
    technicalPenalty
);

return [
  {
    json: {
      ...input,

      auditResult: {
        status: auditStatus,

        healthScore,

        counts: {
          totalFindings: counts.total,
          info: counts.info,
          warnings: counts.warnings,
          errors: counts.errors,
          technicalErrors: counts.technicalErrors,
          affectedObjects: counts.affectedObjects
        },

        rules: {
          passed:
            counts.errors === 0 &&
            counts.warnings === 0 &&
            counts.technicalErrors === 0,

          warning:
            counts.errors === 0 &&
            counts.technicalErrors === 0 &&
            counts.warnings > 0,

          failed:
            counts.errors > 0 ||
            counts.technicalErrors > 0
        }
      }
    }
  }
];

const input = $input.first().json;

const workflow = input.workflow ?? {
  id: "WF-0010",
  name: "Object Auditor",
  version: "0.1.0",
  status: "draft"
};

const auditResult = input.auditResult ?? {
  status: "failed",
  healthScore: 0,
  counts: {
    totalFindings: 0,
    info: 0,
    warnings: 0,
    errors: 0,
    technicalErrors: 1,
    affectedObjects: 0
  }
};

const auditContext = input.auditContext ?? {};
const auditFindings = input.auditFindings ?? {};

const objects = Array.isArray(auditContext.objects)
  ? auditContext.objects
  : [];

const registryEntries = Array.isArray(auditContext.registryEntries)
  ? auditContext.registryEntries
  : [];

const findings = Array.isArray(auditFindings.all)
  ? auditFindings.all
  : [];

const technicalErrors = Array.isArray(auditFindings.technicalErrors)
  ? auditFindings.technicalErrors
  : [];

return [
  {
    json: {
      workflow: {
        id: workflow.id,
        name: workflow.name,
        version: workflow.version,
        status: workflow.status
      },

      auditStatus: auditResult.status,
      healthScore: auditResult.healthScore,

      summary: {
        checkedObjects: objects.length,
        checkedRegistryEntries: registryEntries.length,
        totalFindings: auditResult.counts?.totalFindings ?? findings.length,
        info: auditResult.counts?.info ?? 0,
        warnings: auditResult.counts?.warnings ?? 0,
        errors: auditResult.counts?.errors ?? 0,
        technicalErrors:
          auditResult.counts?.technicalErrors ??
          technicalErrors.length,
        affectedObjects:
          auditResult.counts?.affectedObjects ?? 0
      },

      findings,

      groupedFindings: {
        info: auditFindings.grouped?.info ?? [],
        warnings: auditFindings.grouped?.warnings ?? [],
        errors: auditFindings.grouped?.errors ?? []
      },

      technicalErrors,

      affectedObjectIds:
        auditFindings.affectedObjectIds ?? [],

      safety: {
        readOnly: true,
        filesChanged: false,
        registriesChanged: false,
        commitsCreated: false,
        automaticRepair: false,
        reviewRequired:
          auditResult.status !== "passed"
      },

      source: {
        objectData:
          input.source?.workflowId ??
          "WF-0008",
        registryMode:
          input.registry?.source ??
          "controlled_test_data"
      },

      timestamp: new Date().toISOString()
    }
  }
];
